  Image
    *clone_image = (Image *) NULL,
    *new_image = (Image *) NULL;

  ImageInfo
    *clone_info = (ImageInfo *) NULL;

  char
    filename[MagickPathExtent];

  MagickBooleanType
    status;

  clone_info = CloneImageInfo(image_info);
  GetPathInfo(filename, MagickPathExtent, image, exception);
  (void) FormatLocaleString(filename, MagickPathExtent, "%s-%s", GetImageBlobFilepath(image), GetPathComponent(filename, MagickFilenameComponent));

