Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                               MagickOffsetType PS_Offset, ssize_t PS_Size,
                               ExceptionInfo *exception) {
  Image *new_image = (Image *) NULL;
  ImageInfo *clone_info;
  char filename[MaxTextLength];
  FILE *file;
  MagickBooleanType status;
  size_t len;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename, WritePath, filename, MaxTextLength);
  (void) FormatLocaleString(filename, MaxTextLength, "%s-%s", filename,
                            GetImageBlobOffset(image));

  file = fopen(filename, "w+b");
  if (file == (FILE *) NULL) {
    ThrowFileException(exception, FileOpenError, filename, PS_Offset);
    return (Image *) NULL;
  }

  status = WriteBlobFile(file, image, PS_Offset, PS_Size);
  if (status == MagickFalse) {
    fclose(file);
    return (Image *) NULL;
  }

  (void) fseek(file, 0, SEEK_SET);
  new_image = ReadImage(clone_info, file, exception);
  (void) fclose(file);

  if (new_image == (Image *) NULL)
    return image;

  if (image->next != (Image *) NULL)
    CloneNextImage(image, new_image);

  if (image->previous != (Image *) NULL)
    ClonePreviousImage(image, new_image);

  len = strlen("postscript:");
  if ((new_image->format != (const char *) NULL) &&
      (LocaleCompare(new_image->format, "postscript") != 0) &&
      (LocaleCompare(new_image->magick, "Postscript") == 0))
    (void) SetImageFormat(new_image, "postscript");

  (void) CloneImageAttributes(image, new_image);
  (void) CloneImageProfiles(image, new_image);
  (void) CloneImageArtifacts(image, new_image);

  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  ImageInfo *clone_info;
  char filename[MaxTextLength];
  FILE *file;
  Image *new_image;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename, Filename, filename);
  (void) CopyMagickString(clone_info->filename, filename, MaxTextLength);
  file = fopen(clone_info->filename, "wb");
  if (file == (FILE *) NULL) {
    ThrowFileException(exception, FileOpenError, CannotOpenFile, clone_info->filename);
    return (Image *) NULL;
  }

  if (WriteBlobFile(file, PS_Offset, PS_Size, image) != PS_Size) {
    fclose(file);
    return image;
  }

  (void) fclose(file);
  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    return image;

  (void) CloneImageAttributes(image, new_image);
  return ReplaceImage(image, new_image, exception);
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  Image
    *clone_image = (Image *) NULL,
    *new_image = (Image *) NULL;

  ImageInfo
    *clone_info = (ImageInfo *) NULL;

  MagickBooleanType
    status;

  char
    filename[MagickPathExtent];

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    goto cleanup;

  GetPathComponent(image->filename, Head, filename, (char *) NULL);
  (void) CopyMagickString(clone_info->filename, filename, MagickPathExtent);
  GetPathComponent(clone_info->filename, Tail, filename, (char *) NULL);
  (void) CopyMagickString(clone_info->filename, filename, MagickPathExtent);

  status = WriteImage(clone_info, image, exception);
  if (status == MagickFalse)
    goto cleanup;

  clone_image = CloneImage(image, 0, 0, MagickTrue, exception);
  if (clone_image == (Image *) NULL)
    goto cleanup;

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    goto cleanup;

  (void) CloneImageAttributes(image, new_image);
  image = new_image;

cleanup:
  if (clone_info != (ImageInfo *) NULL)
    clone_info = DestroyImageInfo(clone_info);
  if (clone_image != (Image *) NULL)
    clone_image = DestroyImage(clone_image);
  return image;
}

#include <stdio.h>
#include <stdlib.h>

#include "MagickCore/magic.h"
#include "MagickCore/blob.h"
#include "MagickCore/exception.h"
#include "MagickCore/image.h"
#include "MagickCore/image_info.h"

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  Image
    *clone_image,
    *new_image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  char
    filename[MaxTextLength];

  size_t
    length;

  ssize_t
    count;

  unsigned char
    *blob;

  (void) CloneImageInfo(image_info, exception);
  clone_info = CloneImageInfo(image_info);
  GetPathComponent(clone_info->filename,FileName,filename);
  if (filename[0] == '\0')
    (void) CopyMagickString(filename, "ps:", MaxTextLength);
  length=(size_t) PS_Size;
  blob=(unsigned char *) AcquireMemory(length);
  if (blob == (unsigned char *) NULL)
    {
      clone_info=DestroyImageInfo(clone_info);
      return(image);
    }
  count=ReadBlob(image, (size_t) PS_Size, blob);
  if (count != PS_Size)
    {
      clone_info=DestroyImageInfo(clone_info);
      blob=(unsigned char *) RelinquishMemory(blob);
      return(image);
    }
  (void) FormatLocaleString(filename,MaxTextLength,"%s",GetImageBlob(clone_info,blob,length,exception));
  clone_info=DestroyImageInfo(clone_info);
  blob=(unsigned char *) RelinquishMemory(blob);
  if (IsBlobPS(filename) == MagickFalse)
    return(image);
  clone_image=CloneImage(image,0,0,MagickTrue,exception);
  if (clone_image == (Image *) NULL)
    return(image);
  new_image=ReadImage(clone_image,filename,exception);
  if (new_image == (Image *) NULL)
    {
      clone_image=DestroyImage(clone_image);
      return(image);
    }
  clone_image=DestroyImage(clone_image);
  status=SetImage(clone_image,new_image->columns,new_image->rows,MagickTrue,exception);
  if (status == MagickFalse)
    {
      new_image=DestroyImage(new_image);
      return(image);
    }
  (void) CopyMagickString(clone_image->magick,new_image->magick,MaxTextLength);
  (void) CopyMagickString(clone_image->filename,new_image->filename,MaxTextLength);
  (void) CopyMagickString(clone_image->scene,new_image->scene,MaxTextLength);
  (void) CopyMagickString(clone_image->tiff,clone_image->tiff,MaxTextLength);
  (void) CopyMagickString(clone_image->unique,clone_image->unique,MaxTextLength);
  clone_image=DestroyImage(clone_image);
  return(new_image);
}
